// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    GreedyReceiver greedy;

    function setUp() public {
        c = new MyContract();
        greedy = new GreedyReceiver();
    }

    function testFuzz_property(uint256 amount) public {
        vm.deal(address(c), 1 ether);
        amount = bound(amount, 0, 1 ether);

        bool ok;
        try c.sendTo(address(greedy), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a transfer with a 2300-gas stipend to a receiver that burns more
        // gas always fails and C reverts; the mutant swallows the failed call
        // and succeeds.
        assertTrue(ok == false, "sendTo must revert on failing transfer");
    }
}

contract GreedyReceiver {
    receive() external payable {
        assembly {
            sstore(0, add(sload(0), 1))
        }
    }
}
